('cargo_logistics','logistics','Logística de Cargas','Amplia a organização das frotas mercantis.',3,'{merchant_hulls,caravan_routes}',5,'{"cedar":280,"stone":150,"oil":160,"gold":240}',2400,'{"unlock":"advanced_cargo"}',11),
('coastal_watch','defense','Vigilância Costeira','Forma tripulações para patrulhar portos.',1,'{watchtowers}',2,'{"cedar":130,"stone":110,"oil":70,"gold":110}',900,'{"unlock":"watch_boats"}',12),
('shield_formation','defense','Formação de Escudos','Desbloqueia defensores organizados.',2,'{watchtowers}',3,'{"wheat":160,"cedar":120,"stone":150,"gold":140}',1500,'{"unlock":"spearmen"}',13),
